function speakingSections(pack: SpeakingPack, id: string): ContentSection[] {
  return [{ id: `${id}-part1`, title: "Part 1 — Introduction and interview", text: pack.part1.map((q, i) => `${i + 1}. ${q}`).join("\n"), instructions: "Allow 4–5 minutes. Answer naturally, with relevant details." },
    { id: `${id}-part2`, title: "Part 2 — Individual long turn", text: pack.cue, cuePoints: pack.points, instructions: "You have one minute to prepare. Then speak for one to two minutes." },
    { id: `${id}-part3`, title: "Part 3 — Discussion", text: pack.part3.map((q, i) => `${i + 1}. ${q}`).join("\n"), instructions: "Allow 4–5 minutes for broader discussion." }];
}
