export const band8GrammarLessons: StoredContent[] = grammarPacks.map((pack, serial) => {
  const id = `grammar-v4-band8-lesson-${serial + 1}`;
  const questions = pack.rows.trim().split("\n").map((row, i) => {
    const [prompt, answer, a, b, c, explanation] = row.split("|");
    if (![prompt, answer, a, b, c, explanation].every(Boolean)) throw new Error(`Incomplete advanced grammar row ${id}/${i}`);
    const choices = [answer!, a!, b!, c!]; const offset = (serial + i) % 4;
    return { id: `${id}-q${i + 1}`, number: i + 1, type: "choice" as const, prompt: prompt!, answer: answer!, options: [...choices.slice(offset), ...choices.slice(0, offset)], explanation: explanation!, evidence: pack.rule, sectionIndex: 0, subskill: pack.title.toLowerCase().replace(/[^a-z]+/g, "-") };
  });
  return { ...base(id, "grammar", serial % 2 ? 8 : 7.5, pack.topic), title: pack.title, description: "Six contextual advanced grammar decisions, with distinct distractors and Vietnamese explanations.", durationMinutes: 15, sections: [{ id: `${id}-section`, title: pack.title, text: `${pack.rule}\n\nIndependent examples: ${pack.example}`, instructions: "Read the explanation, choose the contextual answer, and review the meaning and form after submission." }], questions, tags: ["band8-extension", "advanced-grammar"], objectives: ["Control the grammatical forms in context.", "Check logical subject, reference, scope and time rather than selecting a familiar phrase."] };
});
